 "content": "def transform(grid):
    """Copy the horizontal seed pattern onto each isolated marker cell."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter

    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    # Locate the longest horizontal contiguous non-background run: this is
    # the seed object, while the remaining non-background cells are markers.
    best = None
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            if best is None or c - start > best[2] - best[1]:
                best = (r, start, c)
    if best is None:
        return g
    sr, sc, se = best
    pattern = g[sr][sc:se]
    seed_cells = {(sr, c) for c in range(sc, se)}
    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != background and (r, c) not in seed_cells]
    anchor = len(pattern) // 2
    for r, c in markers:
        left = c - anchor
        for j, value in enumerate(pattern):
            x = left + j
            if 0 <= x < w:
                g[r][x] = value
    return g
